const QcaNativeScan*qca_scan_native_view(void);
static int qeth_fault(QethPolicy*p,unsigned error){p->phase=QETH_FAULT;p->error=error;if(p->station)qsg_revoke(p->station,error);return -1;}
int qeth_policy_begin(QethPolicy*p,QsgNative*g,uint64_t now){if(!p||p->phase||!g||!g->data||!g->station||g->fault||g->mgmt.phase!=STX_DONE||g->station->quarantined||g->epoch!=g->data->epoch||!now||now>UINT64_MAX-3000000||!apart(p,sizeof(*p),g,sizeof(*g))||!live(g->data,now))return 0;const QcaNativeScan*c=qca_scan_native_view();if(!c||c->radio!=g->data->radio||c->epoch!=g->epoch||c->phase!=QCA_NATIVE_SCAN_LIVE_DONE||c->tx.phase!=QCA_TX_IDLE)return 0;
 if(!apart(p,sizeof(*p),c,sizeof(*c))||!apart(p,sizeof(*p),g->data,sizeof(*g->data))||!apart(p,sizeof(*p),g->station,sizeof(*g->station)))return 0;for(unsigned j=0;j<47;j++){const QcaDmaBuffer*b=j<14?&g->data->runtime->ce[j]:&g->data->runtime->extra[j-14];if(!apart(p,sizeof(*p),b->host,(size_t)b->bytes))return 0;}
 uint8_t command[20]={0};w32(command,WMI_TLV_VDEV_SET_PARAM_CMDID);w16(command+4,sizeof(struct wmi_vdev_set_param_cmd));w16(command+6,WMI_TLV_TAG_STRUCT_VDEV_SET_PARAM_CMD);struct wmi_vdev_set_param_cmd body={0};body.vdev_id=g->station->vdev;body.param_id=WMI_TLV_VDEV_PARAM_TX_ENCAP_TYPE;body.param_value=1; /* Exact upstream vif policy uses NATIVE_WIFI1, descriptor remains ETH2. */copy(command+8,&body,sizeof body);uint32_t request=0;QcaPersistentTx*t=(QcaPersistentTx*)&c->tx;if(!qca_tx_submit(t,command,sizeof command,now,3000000,&request))return 0;QethPolicy next={g,t,g->epoch,now,now+3000000,QETH_CONFIG_QUEUED,0,request,0,0,0};*p=next;return 1;}
int qeth_policy_poll(QethPolicy*p,uint64_t now){if(!p||!p->station||!p->publisher||p->phase==QETH_FAULT||now<p->last||p->epoch!=p->station->epoch||p->station->fault)return p?qeth_fault(p,200):-1;p->last=now;if(p->phase==QETH_CONFIG_DMA_DONE)return 1;if(now>p->deadline)return qeth_fault(p,201);int rc=qca_tx_poll(p->publisher,now);if(rc<0)return qeth_fault(p,202);if(p->publisher->request!=p->request)return qeth_fault(p,203);if(p->publisher->phase==QCA_TX_POSTED||p->publisher->phase==QCA_TX_DMA_DONE){p->cookie=p->publisher->cookie;p->phase=QETH_CONFIG_PUBLISHED;}if(p->publisher->phase!=QCA_TX_DMA_DONE)return 0;p->dma_serial=p->publisher->completed;if(!p->cookie||!p->dma_serial||!qca_tx_retire(p->publisher,p->request))return qeth_fault(p,204);p->phase=QETH_CONFIG_DMA_DONE;return 1;}
static int key_receipt(const QethPolicy*p,const QsgKeyOp*k,unsigned index){if(!k||k->phase!=QSK_CONFIRMED||k->index!=index||k->epoch!=p->epoch||k->glue!=p->station||k->tx!=p->publisher||!k->pn||k->pn->peer_id!=p->station->station->peer_id||!same(k->pn->peer,p->station->station->peer,6)||!same(k->pn->own,p->station->station->own_mac,6)||k->pn->htt.endpoint!=p->station->data->binding.endpoint||k->pn->htt.op_version!=3||k->pn->version.major!=3||k->pn->version.minor!=56||k->pn->epoch!=p->epoch||k->pn->quarantined||k->pn->pending||!k->pub_cookie||!k->dma_serial||k->pub_cookie>=p->cookie||k->dma_serial>=p->dma_serial||!k->dma_seen||!k->sec_seen||k->sec_raw.completion<=k->pub_floor||!k->pn->key[index].confirmed||k->pn->key[index].sec_completion!=k->sec_raw.completion)return 0;if(k->rsc_bytes!=0&&k->rsc_bytes!=6)return 0;if(index&&k->rsc_bytes!=6)return 0;uint64_t initial=0;for(unsigned j=0;j<k->rsc_bytes;j++)initial|=(uint64_t)k->rsc[j]<<(8*j);if(initial!=k->pn->key[index].initial)return 0;StaEvent event={0};if(sta_decode_htt_bound(&k->sec_raw,&k->pn->htt,&k->pn->version,&event)!=1||event.kind!=STA_SEC_IND||event.peer_id!=p->station->station->peer_id||event.cipher!=6||event.unicast!=(index==0))return 0;return 1;}
int qeth_submit(QethPolicy*p,const QsgKeyOp*ptk,const QsgKeyOp*gtk,const uint8_t*f,unsigned n,uint16_t id,uint64_t now){if(!p||!p->station||!p->station->data||p->phase!=QETH_CONFIG_DMA_DONE||p->error||p->epoch!=p->station->epoch||!f||n<14||n>1514||!id||id==65535||!apart(p,sizeof(*p),f,n)||!apart(p->station,sizeof(*p->station),f,n)||(ptk&&!apart(ptk,sizeof(*ptk),f,n))||(gtk&&!apart(gtk,sizeof(*gtk),f,n)))return 0;QsgNative*g=p->station;QcaHttDataPath*s=g->data;StaJoin*sta=g->station;if(!sta||sta->epoch!=p->epoch||sta->quarantined||!sta->associated||!sta->mapped||sta->pending||!sta->ptk||!sta->gtk||!gtk||gtk->index<1||gtk->index>3||!key_receipt(p,ptk,0)||!key_receipt(p,gtk,gtk->index)||ptk->pub_cookie>=gtk->pub_cookie||ptk->dma_serial>=gtk->dma_serial||ptk->sec_raw.completion>=gtk->sec_raw.completion||!same(f+6,sta->own_mac,6))return 0;unsigned protocol=((unsigned)f[12]<<8)|f[13];if(protocol==0x888e){if(n<113||!same(f,sta->peer,6)||f[14]<1||f[14]>3||f[15]!=3||(((unsigned)f[16]<<8)|f[17])!=n-18)return 0;}else{if(protocol!=0x800&&protocol!=0x806)return 0;if(!sta_local_eligibility_live(sta,s->radio))return 0;}if(!live(s,now)||s->phase!=QDP_RX_ACTIVE||!s->aggr_done||id<=s->tx_id||s->tx_posted||s->runtime->tx_owners||p->pending_id||now>UINT64_MAX-3000000)return 0;QcaInitAdapter*a=adapter(s->radio);QcaCeRing*ce=&a->channels.rings[4];QcaDmaBuffer*d=&a->channels.buffers[9];if(ce->read!=ce->write||!apart(d->host,4096,f,n))return 0;for(unsigned j=0;j<47;j++){const QcaDmaBuffer*b=j<14?&s->runtime->ce[j]:&s->runtime->extra[j-14];if(!apart(b->host,(unsigned)b->bytes,f,n))return 0;}
 uint8_t*out=d->host;unsigned prefetch=((n<50?n:50)+3)&~3u;zero(out,40+prefetch);copy(out+1024,f,n);copy(out+40,f,n<prefetch?n:prefetch);w32(out,(uint32_t)d->address+1024);w32(out+4,n);if(!qca_htc_header(out+16,4080,s->binding.endpoint,16+prefetch,0,0))return 0;out[24]=1;out[25]=2|(2<<5); /* NO_AGGR local bound; MAC_HDR_PRESENT0, NO_ENCRYPT0. */w16(out+26,sta->vdev|(16<<6)|0x800);w16(out+28,n);w16(out+30,id);w32(out+32,(uint32_t)d->address);w32(out+36,65535);p->pending_id=id;s->tx_cookie=0xc0000000u|id;s->tx_id=id;s->tx_bytes=24+prefetch;s->tx_floor=s->radio->rx.completed;s->tx_dma_done=s->tx_htt_done=0;s->tx_posted=1;s->runtime->tx_owners=1;s->transfer_deadline=now+3000000;atomic_thread_fence(memory_order_release);if(qca_ce_post(ce,d->address+16,s->tx_bytes,s->tx_cookie,s->binding.endpoint,0)){qdp_quarantine(s,205);return -1;}return 1;}

int qeth_poll_result(QethPolicy*p,uint64_t now){if(!p||!p->station||!p->station->data||p->phase!=QETH_CONFIG_DMA_DONE||p->error||!p->pending_id||p->epoch!=p->station->epoch)return -1;QcaHttDataPath*d=p->station->data;if(d->tx_id!=p->pending_id)return qeth_fault(p,207);if(qdp_poll_dma(d,now)<0)return qeth_fault(p,d->error?d->error:208);if(d->tx_posted||!d->tx_dma_done||!d->tx_htt_done)return 0;if(d->tx_status!=0){qdp_quarantine(d,206);return qeth_fault(p,206);}p->pending_id=0;return 1;}
